http.createServer(async(req,res)=>{
 res.setHeader('X-Content-Type-Options','nosniff');res.setHeader('X-Frame-Options','DENY');res.setHeader('Referrer-Policy','same-origin');
 try{const url=new URL(req.url,'http://x');
  if(url.pathname.startsWith('/api/'))return await api(req,res,url);
  if(url.pathname==='/health')return send(res,200,{ok:true});
  {const mi=/^\/img\/(\d+)$/.exec(url.pathname);if(mi){const d=db.prepare('SELECT mime,data FROM images WHERE id=?').get(+mi[1]);if(!d){res.writeHead(404);return res.end()}res.writeHead(200,{'Content-Type':d.mime,'Cache-Control':'public, max-age=31536000, immutable'});return res.end(Buffer.from(d.data))}}
  if(url.pathname==='/partner'||url.pathname==='/partner.html'){res.writeHead(302,{Location:'/delivery'});return res.end()}
  const PG={'/':'index.html','/admin':'admin.html','/seller':'seller.html','/delivery':'delivery.html','/driver':'driver.html'};let f=path.normalize(path.join(PUB,PG[url.pathname]||decodeURIComponent(url.pathname)));
  if(!f.startsWith(PUB)||!fs.existsSync(f)||fs.statSync(f).isDirectory())f=path.join(PUB,'index.html');
  res.writeHead(200,{'Content-Type':MIME[path.extname(f)]||'application/octet-stream'});fs.createReadStream(f).pipe(res)
 }catch(e){const c=e.code>=400&&e.code<600?e.code:500;if(c===500)console.error(e);send(res,c,{error:c===500?'Server error':e.message})}
}).listen(PORT,()=>console.log('🚀 Universe running on http://localhost:'+PORT));
